def _terminal_worker_job_exists(job_id: str) -> bool:
    candidates = [
        RESULTS / f"{job_id}.json",
        DONE / f"{job_id}.json",
        REJECTED / f"{job_id}.json",
    ]
    return any(path.is_file() for path in candidates)


def _release_terminal_agent_guard_claim(guard: Path, output: str) -> bool:
    matches = re.findall(r"Scope superpuesto con (worker-[A-Za-z0-9._-]+):", output)
    if not matches:
        return False

    help_result = run([PYTHON_BIN, str(guard), "--help"], cwd=ROOT)
    if help_result.returncode != 0:
        return False

    for agent_id in dict.fromkeys(matches):
        job_id = agent_id[len("worker-"):]
        if not _terminal_worker_job_exists(job_id):
            continue

        for subcommand in ("release", "unregister", "worktree-remove"):
            if not re.search(rf"(?m)^\s*{re.escape(subcommand)}(?:\s|$)", help_result.stdout):
                continue
            subhelp = run([PYTHON_BIN, str(guard), subcommand, "--help"], cwd=ROOT)
            if subhelp.returncode != 0:
                continue
            command = [PYTHON_BIN, str(guard), subcommand]
            if "--agent-id" in subhelp.stdout:
                command.extend(["--agent-id", agent_id])
            if "--task-id" in subhelp.stdout:
                command.extend(["--task-id", job_id])
            if len(command) == 3:
                continue
            released = run(command, cwd=ROOT)
            if released.returncode == 0:
                return True
    return False


